tasks.description:
建立 `apps/web/src/parent/api/children.ts`，型別與 `docs/tasks/api_index.md` §3 一致：
```ts
export interface ChildSummary { id: string; name: string; grade_level: number; class_name: string | null; school_name: string | null; photo_url: string | null; status: 'active' | 'suspended' | 'withdrawn' }
export interface ChildDetail extends ChildSummary { school_class: string | null; enrolled_on: string | null; my_guardian: { relation: GuardianRelation; is_primary: boolean; can_pickup: boolean; receives_notifications: boolean } }
export interface ParentMe { id: string; display_name: string | null; picture_url: string | null; phone: string | null; children: ChildSummary[] }
export function getMe(): Promise<ParentMe>              // GET /parent/me（BACKEND-064）
export function listChildren(): Promise<ChildSummary[]> // GET /parent/children（BACKEND-184）
export function getChild(id: string): Promise<ChildDetail> // GET /parent/children/{id}（BACKEND-185）
export interface ChildToday {
  student_id: string; date: string; is_service_day: boolean
  attendance: { status: AttendanceStatus | null; check_in_at: string | null; check_out_at: string | null }
  on_leave: boolean
  leave: { id: string; leave_type: LeaveType; leave_type_label: string; start_date: string; end_date: string } | null
  homework: { item_count: number; done_count: number; overall_status: HomeworkOverallStatus; ready_eta: string | null; note: string | null }
  pickup_request: { id: string; status: PickupRequestStatus; expected_arrival_at: string | null; reply_ready_eta: string | null; reply_message: string | null; reply_source: 'auto' | 'staff' | null; completed_at: string | null; picked_up_by_name: string | null; can_cancel: boolean; can_mark_arrived: boolean } | null
}
export function getChildToday(id: string): Promise<ChildToday> // GET /parent/children/{id}/today（BACKEND-526，首頁今日狀態聚合）
```
enum 型別（AttendanceStatus、LeaveType、HomeworkOverallStatus、PickupRequestStatus、PickupReplySource、StudentStatus、GuardianRelation）由 FRONTEND-002 import，`status`、`reply_source`、`relation` 欄位即使用這些型別；全部欄位與後端 `apps/api/app/schemas/parent_children.py` 逐欄一致。`pickup_request` 由後端優先取今日非終態那筆、否則今日最新一筆；營業日無出勤列時 attendance.status 為 `expected`、非營業日為 null。
全部走 PARENT-004 的 `parentHttp`，回傳 `response.data`。移植 ivy `FE:src/parent/api/profile.ts::getMe` 的用途；路徑改為本專案規格（ivy 的 `/parent/my-children`、`home/summary` 不移植）。

**驗收標準**：每一條對應 red_case。

建立 `apps/web/src/parent/api/homework.ts`（型別依 `docs/tasks/api_index.md` §14 BACKEND-391）：
```ts
// HomeworkItemStatus / HomeworkOverallStatus / HHMM / ISODate 由 FRONTEND-002 import
export interface HomeworkToday { student_id: string; date: string; items: { title: string; subject_name: string | null; status: HomeworkItemStatus }[]; overall_status: HomeworkOverallStatus; ready_eta: string | null; note: string | null; updated_at: string | null }
export function getChildHomework(childId: string, date?: string): Promise<HomeworkToday>  // GET /parent/children/{id}/homework?date=
```
date 省略時不帶 query（後端以今日為準）。走 PARENT-004 `parentHttp`。

**驗收標準**：每一條對應 red_case。

建立 `apps/web/src/parent/api/attendance.ts`（BACKEND-323）：
```ts
// AttendanceStatus / LeaveType 由 FRONTEND-002 import
export interface AttendanceDay { date: string; is_service_day: boolean; status: AttendanceStatus | null; check_in_at: string | null; check_out_at: string | null; leave_type: LeaveType | null }
export interface MonthlyAttendance { student_id: string; month: string; days: AttendanceDay[]; stats: { service_days: number; attended: number; absent: number; leave: number; unrecorded: number } }
export function getChildAttendance(childId: string, month: string /* YYYY-MM */): Promise<MonthlyAttendance> // GET /parent/children/{id}/attendance?month=
```
走 PARENT-004 `parentHttp`。參考 ivy `FE:src/parent/api/attendance.ts::getMonthlyAttendance` 的用途；路徑與參數改為本專案（ivy 用 year / month 兩參數與 student_id query）。

**驗收標準**：每一條對應 red_case。
